    rep = ['www.','cpanel.','ns1.','ns2.','ns3.','ns4.','cpcontacts.','cpcalendars.','webdisk.','hostmaster.','autodiscover.','webmail.','smtp.','whm.','mail.','facebook.','youtube.','whatsapp.']
    if '<' not in str(i) and '>' not in str(i):
        for x in rep:
            i = str(i).replace(x,'')
